CREATE POLICY "All users can view caption example categories" ON "public"."caption_example_categories" AS PERMISSIVE FOR SELECT TO "authenticated" USING (true);

CREATE POLICY "Only superadmins can create caption example categories" ON "public"."caption_example_categories" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (( SELECT public.is_superadmin(auth.uid()) AS is_superadmin));

CREATE POLICY "Only superadmins can delete caption example categories" ON "public"."caption_example_categories" AS PERMISSIVE FOR DELETE TO "authenticated" USING (( SELECT public.is_superadmin(auth.uid()) AS is_superadmin));

CREATE POLICY "Only superadmins can update caption example categories" ON "public"."caption_example_categories" AS PERMISSIVE FOR UPDATE TO "authenticated" USING (( SELECT public.is_superadmin(auth.uid()) AS is_superadmin)) WITH CHECK (( SELECT public.is_superadmin(auth.uid()) AS is_superadmin));

CREATE POLICY "experiment_findings - all authenticated" ON "public"."experiment_findings" AS PERMISSIVE FOR ALL TO "authenticated" USING (true) WITH CHECK (true);

CREATE POLICY "experiments - all authenticated" ON "public"."experiments" AS PERMISSIVE FOR ALL TO "authenticated" USING (true) WITH CHECK (true);

CREATE POLICY "image_reaction_profiles - delete authenticated" ON "public"."image_reaction_profiles" AS PERMISSIVE FOR DELETE TO "authenticated" USING (true);

CREATE POLICY "image_reaction_profiles - insert authenticated" ON "public"."image_reaction_profiles" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (true);

CREATE POLICY "image_reaction_profiles - select authenticated" ON "public"."image_reaction_profiles" AS PERMISSIVE FOR SELECT TO "authenticated" USING (true);

CREATE POLICY "image_reaction_profiles - update authenticated" ON "public"."image_reaction_profiles" AS PERMISSIVE FOR UPDATE TO "authenticated" USING (true) WITH CHECK (true);

CREATE POLICY "reaction_joke_shares - insert own" ON "public"."reaction_joke_shares" AS PERMISSIVE FOR INSERT TO PUBLIC WITH CHECK ((auth.uid() = profile_id));

CREATE POLICY "reaction_joke_shares - select authenticated" ON "public"."reaction_joke_shares" AS PERMISSIVE FOR SELECT TO PUBLIC USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "reaction_joke_workshops - insert own" ON "public"."reaction_joke_workshops" AS PERMISSIVE FOR INSERT TO PUBLIC WITH CHECK ((auth.uid() = profile_id));

CREATE POLICY "reaction_joke_workshops - select authenticated" ON "public"."reaction_joke_workshops" AS PERMISSIVE FOR SELECT TO PUBLIC USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "reaction_joke_workshops - update own" ON "public"."reaction_joke_workshops" AS PERMISSIVE FOR UPDATE TO PUBLIC USING ((auth.uid() = profile_id)) WITH CHECK ((auth.uid() = profile_id));

CREATE POLICY "sidechat_clusterings - all authenticated" ON "public"."sidechat_clusterings" AS PERMISSIVE FOR ALL TO "authenticated" USING (true) WITH CHECK (true);

CREATE POLICY "Authenticated uploads to images" ON "storage"."objects" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ((bucket_id = 'images'::text));

CREATE POLICY "Public images are viewable by everyone" ON "storage"."objects" AS PERMISSIVE FOR SELECT TO PUBLIC USING ((bucket_id = 'images'::text));

CREATE POLICY "Superadmins can delete images" ON "storage"."objects" AS PERMISSIVE FOR DELETE TO PUBLIC USING (((bucket_id = 'images'::text) AND (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.is_superadmin = true))))));

CREATE POLICY "Superadmins can update images" ON "storage"."objects" AS PERMISSIVE FOR UPDATE TO PUBLIC USING (((bucket_id = 'images'::text) AND (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.is_superadmin = true))))));

CREATE POLICY "Superadmins can upload images" ON "storage"."objects" AS PERMISSIVE FOR INSERT TO PUBLIC WITH CHECK (((bucket_id = 'images'::text) AND (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.is_superadmin = true))))));

CREATE VIEW "public"."experiment_scorecards" AS
 WITH vote_tallies AS (
         SELECT e_1.id AS experiment_id,
            count(*) FILTER (WHERE ((cv.vote_value > 0) AND cv.is_from_study)) AS up_study,
            count(*) FILTER (WHERE ((cv.vote_value < 0) AND cv.is_from_study)) AS down_study,
            count(*) FILTER (WHERE (cv.vote_value > 0)) AS up_all,
            count(*) FILTER (WHERE (cv.vote_value < 0)) AS down_all,
            count(DISTINCT cv.profile_id) FILTER (WHERE cv.is_from_study) AS voters_study,
            count(DISTINCT cv.profile_id) AS voters_all,
            count(DISTINCT scm.caption_id) AS n_captions
           FROM ((public.experiments e_1
             JOIN public.study_caption_mappings scm ON ((scm.study_id = e_1.study_id)))
             LEFT JOIN public.caption_votes cv ON ((cv.caption_id = scm.caption_id)))
          WHERE (e_1.study_id IS NOT NULL)
          GROUP BY e_1.id
        ), resolved AS (
         SELECT t.experiment_id,
            t.up_study,
            t.down_study,
            t.up_all,
            t.down_all,
            t.voters_study,
            t.voters_all,
            t.n_captions,
                CASE
                    WHEN ((t.up_study + t.down_study) > 0) THEN t.up_study
                    ELSE t.up_all
                END AS up,
                CASE
                    WHEN ((t.up_study + t.down_study) > 0) THEN t.down_study
                    ELSE t.down_all
                END AS down,
                CASE
                    WHEN ((t.up_study + t.down_study) > 0) THEN t.voters_study
                    ELSE t.voters_all
                END AS voters,
            ((t.up_study + t.down_study) > 0) AS votes_are_study_only
           FROM vote_tallies t
        )
 SELECT e.id AS experiment_id,
    e.hypothesis,
    e.goal_metric,
    e.status,
    r.n_captions,
    r.up,
    r.down,
    r.voters,
    r.votes_are_study_only,
        CASE
            WHEN ((r.up + r.down) = 0) THEN NULL::numeric
            ELSE round(((r.up)::numeric / ((r.up + r.down))::numeric), 3)
        END AS funny_rate,
    ((e.goal_metric ->> 'target'::text))::numeric AS target,
        CASE
            WHEN ((r.up + r.down) = 0) THEN NULL::boolean
            ELSE (round(((r.up)::numeric / ((r.up + r.down))::numeric), 3) >= ((e.goal_metric ->> 'target'::text))::numeric)
        END AS target_met
   FROM (public.experiments e
     JOIN resolved r ON ((r.experiment_id = e.id)));

ALTER VIEW "public"."experiment_scorecards" OWNER TO "postgres";

