GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON TABLE "public"."experiment_scorecards" TO "service_role";

CREATE VIEW "public"."v_caption_controversy" AS
 SELECT c.id,
    c.content,
    i.url AS image_url,
    count(cv.id) AS total_votes,
    sum(
        CASE
            WHEN (cv.vote_value = 1) THEN 1
            ELSE 0
        END) AS likes,
    sum(
        CASE
            WHEN (cv.vote_value = '-1'::integer) THEN 1
            ELSE 0
        END) AS dislikes,
    abs(((sum(cv.vote_value))::double precision / (NULLIF(count(cv.id), 0))::double precision)) AS controversy_score
   FROM ((public.captions c
     JOIN public.caption_votes cv ON ((cv.caption_id = c.id)))
     JOIN public.images i ON ((i.id = c.image_id)))
  WHERE ((c.is_public = true) AND (i.is_public = true) AND (i.url IS NOT NULL))
  GROUP BY c.id, c.content, i.url
 HAVING (count(cv.id) >= 5);

