CREATE VIEW "public"."v_caption_trending_week" AS
 SELECT c.id,
    c.content,
    i.url AS image_url,
    count(cv.id) AS vote_count
   FROM ((public.caption_votes cv
     JOIN public.captions c ON ((cv.caption_id = c.id)))
     JOIN public.images i ON ((c.image_id = i.id)))
  WHERE ((cv.created_datetime_utc > (now() - '7 days'::interval)) AND (c.is_public = true) AND (i.is_public = true) AND (i.url IS NOT NULL))
  GROUP BY c.id, c.content, i.url;

ALTER VIEW "public"."v_caption_trending_week" OWNER TO "postgres";

REVOKE ALL ON TABLE "public"."v_caption_trending_week" FROM PUBLIC, anon, authenticated, service_role;

GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON TABLE "public"."v_caption_trending_week" TO "anon";

GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON TABLE "public"."v_caption_trending_week" TO "authenticated";

GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON TABLE "public"."v_caption_trending_week" TO "postgres";

GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON TABLE "public"."v_caption_trending_week" TO "service_role";

CREATE OR REPLACE FUNCTION public.select_random_images(limit_count integer DEFAULT 25)
 RETURNS TABLE(id uuid, url text)
 LANGUAGE sql
 STABLE
AS $function$
    select images.id, images.url
    from public.images
    where images.url is not null
    order by random()
    limit limit_count;
  $function$;

ALTER FUNCTION public.select_random_images(limit_count integer) OWNER TO "postgres";

REVOKE ALL ON FUNCTION public.select_random_images(limit_count integer) FROM PUBLIC, anon, authenticated, service_role;

GRANT EXECUTE ON FUNCTION public.select_random_images(limit_count integer) TO "anon";

GRANT EXECUTE ON FUNCTION public.select_random_images(limit_count integer) TO "authenticated";

GRANT EXECUTE ON FUNCTION public.select_random_images(limit_count integer) TO "postgres";

GRANT EXECUTE ON FUNCTION public.select_random_images(limit_count integer) TO "service_role";

GRANT EXECUTE ON FUNCTION public.select_random_images(limit_count integer) TO PUBLIC;

ALTER PUBLICATION supabase_realtime ADD TABLE public.captions;

